int predict(const float* features, uint8_t* predicted_class, uint16_t* votes_out) {
    uint16_t votes[kNumClasses] = {0};
    for (uint32_t tree = 0; tree < kNumTrees; ++tree) {
        uint32_t node_index = kTreeRoots[tree];
        while (kNodes[node_index].feature != 255) {
            const Node& node = kNodes[node_index];
            node_index = (features[node.feature] <= node.threshold) ? node.left_child : node.right_child;
        }
        ++votes[kNodes[node_index].leaf_class];
    }
    uint8_t best = 0;
    for (uint8_t c = 1; c < kNumClasses; ++c) {
        if (votes[c] > votes[best]) best = c;
    }
    for (uint8_t c = 0; c < kNumClasses; ++c) votes_out[c] = votes[c];
    *predicted_class = best;
    return 0;
}
